static String SelectInst(const GemmNode &op, int block_size, Target target) {
  if (op.isWgmma_) {
    if (!AllowWgmma(op, block_size, target)) {
      FatalWgmmaUnavailable(op, target);
    }
    return kCudaWGMMA;
  }
  if (op.isTcgen05_) {
    if (!AllowTcgen5Mma(op, target)) {
      FatalTcgen5Unavailable(op, target);
    }
    return kCudaTCGEN05;
  }

  if (AllowTcgen5Mma(op, target)) {
    return kCudaTCGEN05;
  }
  if (AllowWgmma(op, block_size, target)) {
    return kCudaWGMMA;
  }
  return kCudaMMA;
}

